import { hashSeed } from '@/lib/ink/rng'
import { measureText } from '@/lib/ink/art/glyph-text'
import type { ArtColour, ArtDef, BadgeGen, Part } from '@/lib/ink/art/types'

export type BadgeOpts = Partial<Omit<BadgeGen, 'gen' | 'text' | 'kind'>> & { fill?: ArtColour }

const r1 = (v: number): number => Math.round(v * 10) / 10
const rad = (d: number): number => (d * Math.PI) / 180

function lcg(seed: number): () => number {
  let s = (seed % 2147483646) + 1
  return () => ((s = (s * 16807) % 2147483647) / 2147483647 - 0.5) * 2
}

function seal(cx: number, cy: number, r0: number, r1_: number, n: number, rot: number, jit: number, rnd: () => number): string {
  const V: Array<[number, number]> = []
  const C: Array<[number, number]> = []
  for (let i = 0; i < n; i++) {
    const a0 = rad(rot + (i / n) * 360), a1 = rad(rot + ((i + 1) / n) * 360), am = (a0 + a1) / 2
    V.push([cx + Math.cos(a0) * (r0 + rnd() * jit), cy + Math.sin(a0) * (r0 + rnd() * jit)])
    C.push([cx + Math.cos(am) * (r1_ + rnd() * jit), cy + Math.sin(am) * (r1_ + rnd() * jit)])
  }
  let d = `M${r1(V[0][0])} ${r1(V[0][1])}`
  for (let i = 0; i < n; i++) d += ` Q${r1(C[i][0])} ${r1(C[i][1])} ${r1(V[(i + 1) % n][0])} ${r1(V[(i + 1) % n][1])}`
  return d + ' Z'
}

function burst(cx: number, cy: number, ro: number, ri: number, n: number, rot: number, jit: number, rnd: () => number): string {
  let d = ''
  for (let i = 0; i < n * 2; i++) {
    const a = rad(rot + (i / (n * 2)) * 360 + rnd() * 1.5)
    const rr = (i % 2 ? ri : ro) + rnd() * jit
    d += `${i ? ' L' : 'M'}${r1(cx + Math.cos(a) * rr)} ${r1(cy + Math.sin(a) * rr)}`
  }
  return d + ' Z'
}

const j = (v: number, rnd: () => number, a = 0.35): number => r1(v + rnd() * a)

interface Shape {
  outline: string
  under?: Part[]
  ring?: string
  text: { x: number; y: number; w: number; em: number }
  sub?: { y: number; w: number }
  over?: Part[]
  deco: { x: number; y: number }
}

function shapeOf(kind: NonNullable<BadgeGen['shape']>, o: BadgeOpts, rnd: () => number): Shape {
  const bumps = o.bumps ?? 12
  const amp = o.amp ?? 3.6
  switch (kind) {
    case 'scallop': {
      const R = 24.4
      return {
        outline: seal(32, 32, R, R + amp, bumps, 6, 0.3, rnd),
        ring: `O 32 32 ${j(19.6, rnd, 0.2)}`,
        text: { x: 32, y: 34, w: 30, em: 21 },
        sub: { y: 45.4, w: 22 },
        deco: { x: 32, y: 21.2 },
      }
    }
    case 'starburst': {
      const n = o.bumps ?? 16
      return {
        outline: burst(32, 32, 26, 21.4, n, -90, 0.4, rnd),
        ring: `O 32 32 ${j(17.6, rnd, 0.2)}`,
        text: { x: 32, y: 33, w: 27, em: 20 },
        sub: { y: 43.5, w: 22 },
        deco: { x: 32, y: 19.6 },
      }
    }
    case 'rosette':
      return {
        outline: seal(32, 26.5, 17.6, 20, o.bumps ?? 16, 4, 0.2, rnd),
        under: [['f', 'tomato', `M21 40.4 L15.4 57.2 L22.4 53.4 L26.6 57.8 L30 43.4 Z`], ['f', 'tomato', `M43 40.4 L48.6 57.2 L41.6 53.4 L37.4 57.8 L34 43.4 Z`], ['s', 'M21 40.4 L15.4 57.2 L22.4 53.4 L26.6 57.8 L30 43.4', 0.9], ['s', 'M43 40.4 L48.6 57.2 L41.6 53.4 L37.4 57.8 L34 43.4', 0.9]],
        ring: `O 32 26.5 ${j(13.6, rnd, 0.2)}`,
        text: { x: 32, y: 28.4, w: 22, em: 16 },
        sub: { y: 38.4, w: 15 },
        deco: { x: 32, y: 17 },
      }
    case 'plate':
      return {
        outline: `M18 ${j(21, rnd)} L46 ${j(20.6, rnd)} Q${j(57.6, rnd)} 21 ${j(57.6, rnd)} 32 Q${j(57.4, rnd)} 43.4 46 43 L18 ${j(43.4, rnd)} Q6.4 43.4 ${j(6.6, rnd)} 32 Q6.4 20.6 18 ${j(21, rnd)} Z`,
        ring: `M15 ${j(24.4, rnd)} L49 ${j(24, rnd)} Q${j(55.6, rnd)} 24 ${j(55.6, rnd)} 32 Q${j(55.4, rnd)} 40 49 ${j(39.8, rnd)} L15 ${j(40, rnd)} Q8.4 40 8.6 32 Q8.4 24.2 15 ${j(24.4, rnd)} Z`,
        text: { x: 32, y: 32.6, w: 38, em: 15 },
        deco: { x: 32, y: 26 },
      }
    case 'shield':
      return {
        outline: `M32 ${j(6.4, rnd)} L${j(54.6, rnd)} 13.6 L${j(54.4, rnd)} 34 C${j(54, rnd)} 45.6 44.4 52.6 32 ${j(57.4, rnd)} C${j(19.6, rnd)} 52.8 ${j(9.8, rnd)} 45.6 ${j(9.8, rnd)} 34 L${j(9.6, rnd)} 13.4 Z`,
        ring: `M32 ${j(11, rnd)} L${j(48.8, rnd)} 17 L${j(48.6, rnd)} 33.6 C48.4 42 41 47.4 32 ${j(51.8, rnd)} C${j(23, rnd)} 47.4 ${j(15.4, rnd)} 42 15.4 33.6 L${j(15.2, rnd)} 17 Z`,
        text: { x: 32, y: 32.4, w: 26, em: 19 },
        sub: { y: 43, w: 19 },
        deco: { x: 32, y: 21 },
      }
    case 'ticket':
      return {
        outline: `M7 ${j(16, rnd)} L57 ${j(15.6, rnd)} L57 28.4 Q52.4 32 57 35.6 L57 ${j(48, rnd)} L7 ${j(48.4, rnd)} L7 35.6 Q11.6 32 7 28.4 Z`,
        ring: `M12.4 ${j(20.6, rnd)} L51.6 ${j(20.4, rnd)} L51.6 ${j(43.6, rnd)} L12.4 ${j(43.8, rnd)} Z`,
        text: { x: 32, y: 33, w: 34, em: 16 },
        sub: { y: 41.6, w: 30 },
        deco: { x: 32, y: 24.6 },
      }
    case 'banner':
      return {
        outline: `M6.6 ${j(19, rnd)} L12 ${j(19, rnd)} L12 ${j(46.4, rnd)} L6.4 46.6 L9.6 32.6 Z M12 19 L52 ${j(18.6, rnd)} L52 ${j(46, rnd)} L12 46.4 Z M52 18.8 L57.6 ${j(19, rnd)} L54.6 32.6 L57.8 46.4 L52 46.2 Z`,
        text: { x: 32, y: 34, w: 36, em: 16 },
        deco: { x: 32, y: 25 },
      }
    case 'medal':
      return {
        outline: seal(32, 37.4, 18.6, 19.6, 22, 0, 0.2, rnd),
        under: [['f', 'tomato', 'M21.6 6.4 L28 6.8 L34.4 22.6 L27.6 24 Z'], ['f', 'tomato', 'M42.4 6.4 L36 6.8 L29.6 22.6 L36.4 24 Z'], ['s', 'M21.6 6.4 L28 6.8 L34.4 22.6', 0.9], ['s', 'M42.4 6.4 L36 6.8 L29.6 22.6', 0.9]],
        ring: `O 32 37.4 ${j(14.6, rnd, 0.2)}`,
        text: { x: 32, y: 41, w: 21, em: 15 },
        deco: { x: 32, y: 28 },
      }
    case 'tag':
    default:
      return {
        outline: `M23 ${j(14.6, rnd)} L${j(41.6, rnd)} 14.4 L50 ${j(22.6, rnd)} L${j(50.4, rnd)} 57.4 L${j(13.8, rnd)} 57.6 L${j(14.2, rnd)} 22.8 Z`,
        over: [['s', 'O 32 22.4 2.6', 0.8], ['s', 'M32.4 19.8 C31.6 11.2 24 5.4 19.6 8.4 C16.4 10.8 20 16.6 25.6 12.4', 0.85]],
        text: { x: 32, y: 38.6, w: 29, em: 15 },
        sub: { y: 50.6, w: 24 },
        deco: { x: 32, y: 51.4 },
      }
  }
}

const star5 = (cx: number, cy: number, ro: number, ri: number): string => {
  let d = ''
  for (let i = 0; i < 10; i++) {
    const a = rad(-90 + i * 36)
    const rr = i % 2 ? ri : ro
    d += `${i ? ' L' : 'M'}${r1(cx + Math.cos(a) * rr)} ${r1(cy + Math.sin(a) * rr)}`
  }
  return d + ' Z'
}

export function badgeSkeleton(text: string, o: BadgeOpts = {}): ArtDef {
  const kind = o.shape ?? 'scallop'
  const rnd = lcg(hashSeed(`${kind}:${text}:${o.color ?? ''}`))
  const shape = shapeOf(kind, o, rnd)
  const color = o.fill ?? o.color ?? 'bubblegum'
  const ink = o.textColor ?? 'ink'
  const ttl = text.toUpperCase()
  const perEm = measureText('hand', ttl, 1)
  const em = r1(Math.min(shape.text.em, shape.text.w / perEm))
  const capH = 0.745 * em
  const build = (small: boolean): Part[] => {
    const parts: Part[] = []
    if (shape.under) parts.push(...shape.under)
    parts.push(['f', color, shape.outline])
    parts.push(['s', shape.outline, small ? 1.15 : 1.05])
    if (shape.ring) parts.push(['c', 'photo', shape.ring, small ? 0.6 : 0.5], ['s', shape.ring, small ? 0.6 : 0.5])
    if (shape.over) parts.push(...shape.over)
    const sub = !small && o.sub && shape.sub
    const ty = shape.text.y + capH / 2 - (sub ? 2 : 0)
    parts.push(['t', ttl, shape.text.x, r1(ty), em, ink, 'hand'])
    if (sub) parts.push(['t', o.sub!, shape.text.x, shape.sub!.y + 2, r1(Math.min(6.4, shape.sub!.w / measureText('hand', o.sub!.toUpperCase(), 1))), ink, 'hand'])
    if (!small && o.deco) {
      const { x, y } = shape.deco
      if (o.deco === 'tick') parts.push(['s', `M${r1(x - 3.8)} ${r1(y + 0.4)} L${r1(x - 1)} ${r1(y + 3)} L${r1(x + 4.2)} ${r1(y - 3)}`, 0.8])
      else if (o.deco === 'star') parts.push(['f', 'lemon', star5(x, y, 3.6, 1.6)], ['s', star5(x, y, 3.7, 1.6), 0.6])
      else if (o.deco === 'sparkle') parts.push(['s', `M${r1(x + 12)} ${r1(y - 4)} L${r1(x + 12.2)} ${r1(y + 2)} M${r1(x + 9)} ${r1(y - 1)} L${r1(x + 15)} ${r1(y - 1.2)}`, 0.8])
      else if (o.deco === 'swoosh') parts.push(['c', 'tomato', `M${r1(shape.text.x - em * 1.1)} ${r1(ty + 3.4)} Q${r1(shape.text.x)} ${r1(ty + 6)} ${r1(shape.text.x + em * 1.2)} ${r1(ty + 2.4)}`, 0.7])
      else if (o.deco === 'percent') parts.push(['c', ink, `O ${r1(x)} ${r1(y)} 3.4`, 0.55], ['c', ink, `M${r1(x - 2)} ${r1(y + 2)} L${r1(x + 2)} ${r1(y - 2)}`, 0.5])
    }
    return parts
  }
  const master = build(false)
  const small = build(true)
  const def: ArtDef = { grid: 64, nibK: 0.05, parts: master, small, kind: 'sticker' }
  if (o.tags) return { ...def, tags: o.tags }
  return def
}

import type { ArtDef, ArtKind, Part } from '@/lib/ink/art/types'

export type P2 = [number, number]

export interface Sub {
  pts: P2[]
  closed: boolean
  anchor: boolean[]
  shape: number
}

export interface ParseOpts {
  step?: number
  rnd?: () => number
}

const TAU = Math.PI * 2
const TOKEN = /[MLlQCOEZ]|-?(?:\d+\.?\d*|\.\d+)(?:e-?\d+)?/g
const CMD = /^[MLlQCOEZ]$/

export function tokenize(d: string): { tok: string[]; bad: string } {
  const tok = d.match(TOKEN) ?? []
  const bad = d.replace(TOKEN, '').replace(/[\s,]+/g, '')
  return { tok, bad }
}

export function parsePath(d: string, o: ParseOpts = {}): Sub[] {
  const step = o.step ?? 0.6
  const rnd = o.rnd ?? (() => 0.5)
  const { tok } = tokenize(d)
  const subs: Sub[] = []
  let cur: Sub | null = null
  let cx = 0, cy = 0, sx = 0, sy = 0, i = 0
  const num = (): number => Number.parseFloat(tok[i++])
  const isNum = (): boolean => i < tok.length && !CMD.test(tok[i])
  const push = (x: number, y: number, anchor: boolean): void => {
    if (!cur) subs.push((cur = { pts: [], closed: false, anchor: [], shape: 0 }))
    cur.pts.push([x, y])
    cur.anchor.push(anchor)
    cx = x
    cy = y
  }
  while (i < tok.length) {
    const c = tok[i++]
    if (c === 'M') {
      cur = null
      sx = num()
      sy = num()
      push(sx, sy, true)
      while (isNum()) push(num(), num(), true)
    } else if (c === 'L') {
      while (isNum()) push(num(), num(), true)
    } else if (c === 'l') {
      while (isNum()) push(cx + num(), cy + num(), true)
    } else if (c === 'Q') {
      while (isNum()) {
        const x1 = num(), y1 = num(), x2 = num(), y2 = num()
        const x0 = cx, y0 = cy
        const n = Math.max(3, Math.ceil(Math.hypot(x2 - x0, y2 - y0) / step))
        for (let k = 1; k <= n; k++) {
          const t = k / n, u = 1 - t
          push(u * u * x0 + 2 * u * t * x1 + t * t * x2, u * u * y0 + 2 * u * t * y1 + t * t * y2, k === n)
        }
      }
    } else if (c === 'C') {
      while (isNum()) {
        const x1 = num(), y1 = num(), x2 = num(), y2 = num(), x3 = num(), y3 = num()
        const x0 = cx, y0 = cy
        const n = Math.max(4, Math.ceil((Math.hypot(x1 - x0, y1 - y0) + Math.hypot(x2 - x1, y2 - y1) + Math.hypot(x3 - x2, y3 - y2)) / step))
        for (let k = 1; k <= n; k++) {
          const t = k / n, u = 1 - t
          push(
            u * u * u * x0 + 3 * u * u * t * x1 + 3 * u * t * t * x2 + t * t * t * x3,
            u * u * u * y0 + 3 * u * u * t * y1 + 3 * u * t * t * y2 + t * t * t * y3,
            k === n,
          )
        }
      }
    } else if (c === 'O') {
      const ox = num(), oy = num(), rx = num(), ry = isNum() ? num() : rx
      cur = null
      const n = Math.max(20, Math.ceil(((rx + ry) * Math.PI * 1.1) / step))
      const a0 = -2.3 + (rnd() - 0.5) * 0.7
      for (let k = 0; k <= n; k++) {
        const a = a0 + (k / n) * TAU * 1.09
        const kk = 1 + 0.02 * Math.sin(2 * a)
        push(ox + Math.cos(a) * rx * kk, oy + Math.sin(a) * ry * kk, false)
      }
      if (cur) {
        const s = cur as Sub
        s.closed = true
        s.shape = Math.round(n / 1.09)
      }
      sx = (cur as Sub | null)?.pts[0][0] ?? ox
      sy = (cur as Sub | null)?.pts[0][1] ?? oy
    } else if (c === 'E') {
      const ox = num(), oy = num(), rx = num(), ry = num()
      const a0 = (num() * Math.PI) / 180, a1 = (num() * Math.PI) / 180
      const ax = ox + Math.cos(a0) * rx, ay = oy + Math.sin(a0) * ry
      if (!cur || Math.hypot(ax - cx, ay - cy) > 0.8) cur = null
      const n = Math.max(6, Math.ceil((Math.abs(a1 - a0) * Math.max(rx, ry)) / step))
      for (let k = 0; k <= n; k++) {
        const a = a0 + ((a1 - a0) * k) / n
        push(ox + Math.cos(a) * rx, oy + Math.sin(a) * ry, k === 0 || k === n)
      }
    } else if (c === 'Z') {
      const s = cur as Sub | null
      if (s && s.pts.length > 2) {
        s.shape = s.pts.length
        const first = s.pts[0], look = s.pts[Math.min(3, s.pts.length - 1)]
        const dl = Math.hypot(look[0] - first[0], look[1] - first[1]) || 1
        const ux = (look[0] - first[0]) / dl, uy = (look[1] - first[1]) / dl
        const ov = 0.9 + rnd() * 1.0
        push(sx, sy, false)
        push(sx + ux * ov * 0.5 - uy * 0.2, sy + uy * ov * 0.5 + ux * 0.2, false)
        push(sx + ux * ov - uy * 0.45, sy + uy * ov + ux * 0.45, false)
        s.closed = true
      }
    }
  }
  for (const s of subs) if (!s.shape) s.shape = s.pts.length
  return subs
}

export function polygonsOf(d: string, o: ParseOpts = {}): P2[][] {
  return parsePath(d, { step: 0.5, ...o }).filter((s) => s.pts.length > 2).map((s) => s.pts.slice(0, s.shape))
}

export interface Problem {
  level: 'error' | 'warn'
  code: string
  msg: string
  at?: string
}

export interface PathCheck {
  errors: string[]
  warnings: string[]
  bbox: [number, number, number, number] | null
  strokes: number
}

const nf = (s: string): number => Number.parseFloat(s)

export function checkPath(d: string): PathCheck {
  const errors: string[] = []
  const warnings: string[] = []
  if (typeof d !== 'string' || !d.trim()) return { errors: ['empty path'], warnings, bbox: null, strokes: 0 }
  const { tok, bad } = tokenize(d)
  if (bad) errors.push(`illegal characters "${bad.slice(0, 12)}" (grammar: M L l Q C O E Z, numbers)`)
  let i = 0
  let open = false
  let count = 0
  let lastPoint = false
  const numsAfter = (): number => {
    let k = 0
    while (i + k < tok.length && !CMD.test(tok[i + k])) k++
    return k
  }
  if (tok.length && tok[0] !== 'M' && tok[0] !== 'O' && tok[0] !== 'E') errors.push(`path must start with M, O or E, not "${tok[0]}"`)
  let curLen = 0
  while (i < tok.length) {
    const c = tok[i++]
    if (!CMD.test(c)) {
      errors.push(`number "${c}" without a command`)
      continue
    }
    const k = numsAfter()
    const bump = (n: number): void => {
      i += n
    }
    switch (c) {
      case 'M':
        if (k < 2 || k % 2) errors.push(`M needs pairs of numbers (got ${k})`)
        open = true
        count++
        curLen = Math.floor(k / 2)
        bump(k)
        break
      case 'L':
        if (!open) errors.push('L before M')
        if (k < 2 || k % 2) errors.push(`L needs pairs of numbers (got ${k})`)
        curLen += Math.floor(k / 2)
        bump(k)
        break
      case 'l':
        if (!open) errors.push('l before M')
        if (k < 2 || k % 2) errors.push(`l needs pairs of numbers (got ${k})`)
        curLen += Math.floor(k / 2)
        bump(k)
        break
      case 'Q':
        if (!open) errors.push('Q before M')
        if (k < 4 || k % 4) errors.push(`Q needs groups of 4 numbers (got ${k})`)
        curLen += Math.floor(k / 4)
        bump(k)
        break
      case 'C':
        if (!open) errors.push('C before M')
        if (k < 6 || k % 6) errors.push(`C needs groups of 6 numbers (got ${k})`)
        curLen += Math.floor(k / 6)
        bump(k)
        break
      case 'O':
        if (k !== 3 && k !== 4) errors.push(`O needs cx cy rx [ry] (got ${k} numbers)`)
        else if (nf(tok[i + 2]) <= 0 || (k === 4 && nf(tok[i + 3]) <= 0)) errors.push('O radii must be positive')
        open = false
        count++
        bump(k)
        break
      case 'E':
        if (k !== 6) errors.push(`E needs cx cy rx ry a0 a1 (got ${k} numbers)`)
        else if (nf(tok[i + 2]) <= 0 || nf(tok[i + 3]) <= 0) errors.push('E radii must be positive')
        if (!open) count++
        open = true
        bump(k)
        break
      case 'Z':
        if (!open || curLen < 3) errors.push('Z closes a stroke of at least 3 points')
        if (k) errors.push('Z takes no numbers')
        open = false
        break
    }
    lastPoint = true
  }
  void lastPoint
  if (!errors.length) {
    const subs = parsePath(d)
    for (const s of subs) {
      if (s.closed || s.pts.length < 4) continue
      const a = s.pts[0], b = s.pts[s.pts.length - 1]
      if (Math.hypot(a[0] - b[0], a[1] - b[1]) < 0.35) warnings.push('the stroke ends exactly where it began: close it with Z (the pen overshoots) or stop short')
    }
    const nums = tok.filter((t) => !CMD.test(t))
    const dec = nums.filter((t) => /\.\d{3,}/.test(t)).length
    if (dec) warnings.push(`${dec} coordinates have 3+ decimals (write one decimal: the engine adds the wobble)`)
    if (nums.length >= 8 && nums.filter((t) => /^-?\d+$/.test(t)).length / nums.length > 0.7) warnings.push('most coordinates are whole numbers: a tidy grid reads as computer-drawn (use 12.2, 11.8...)')
  }
  let bbox: PathCheck['bbox'] = null
  if (!errors.length) {
    for (const s of parsePath(d, { step: 0.4 })) {
      for (let k = 0; k < s.shape; k++) {
        const p = s.pts[k]
        bbox = bbox ? [Math.min(bbox[0], p[0]), Math.min(bbox[1], p[1]), Math.max(bbox[2], p[0]), Math.max(bbox[3], p[1])] : [p[0], p[1], p[0], p[1]]
      }
    }
  }
  return { errors, warnings, bbox, strokes: count }
}

const COLOUR_BASE = new Set([
  'ink', 'ink-soft', 'ink-you', 'pencil', 'pencil-mark', 'red', 'green', 'marker', 'hi', 'focus',
  'paper', 'paper-shade', 'slip', 'card', 'graph', 'kraft', 'check', 'photo', 'desk', 'desk-deep', 'rule-blue', 'rule-red', 'pad', 'pad-rule', 'check-rule',
  'ink-muted', 'pencil-text', 'orange-text', 'hi-deep', 'tape', 'tape-edge',
  'tomato', 'tangerine', 'lemon', 'grass', 'teal', 'sky', 'grape', 'bubblegum',
  'sticky-yellow', 'sticky-green', 'sticky-orange', 'sticky-pink', 'sticky-blue', 'current',
])
export function isArtColour(c: unknown): boolean {
  if (typeof c !== 'string') return false
  if (c === 'acc' || c === 'sil') return true
  const base = c.endsWith('~') ? c.slice(0, -1) : c
  return COLOUR_BASE.has(base) && base !== 'current'
}

export const ACCENT_KEYS = ['tomato', 'tangerine', 'lemon', 'grass', 'teal', 'sky', 'grape', 'bubblegum'] as const

export const USABLE: Partial<Record<ArtKind, [number, number, number, number]>> = {
  icon: [2, 2, 22, 22],
  doodle: [4, 4, 60, 60],
  sticker: [6, 6, 58, 58],
  mascot: [4, 3, 60, 70],
}

export const BUDGET: Record<'icon' | 'doodle' | 'sticker' | 'mascot', { parts: number; small: number; micro: number; hi: number }> = {
  icon: { parts: 6, small: 4, micro: 3, hi: 6 },
  doodle: { parts: 14, small: 9, micro: 5, hi: 8 },
  sticker: { parts: 24, small: 16, micro: 8, hi: 10 },
  mascot: { parts: 34, small: 22, micro: 12, hi: 12 },
}

export function kindOfDef(def: { kind?: ArtKind; grid: ArtDef['grid'] }): ArtKind {
  if (def.kind) return def.kind
  if (def.grid === 24) return 'icon'
  if (Array.isArray(def.grid)) return 'mascot'
  return 'doodle'
}

const PART_TAGS = new Set(['f', 's', 'c', 'd', 'h', 't'])

function widthOf(p: Part): number | undefined {
  if (p[0] === 's') return p[2]
  if (p[0] === 'c') return p[3]
  if (p[0] === 'h') return undefined
  return undefined
}

export type GlyphLookup = (font: string, ch: string) => boolean | undefined

export function validateParts(parts: readonly Part[], kind: ArtKind, tier: string, hasAccent: boolean, glyph?: GlyphLookup): Problem[] {
  const out: Problem[] = []
  const area = USABLE[kind]
  const E = (code: string, msg: string, at: string): number => out.push({ level: 'error', code, msg, at })
  const W = (code: string, msg: string, at: string): number => out.push({ level: 'warn', code, msg, at })
  parts.forEach((p, idx) => {
    const at = `${tier}[${idx}]`
    if (!Array.isArray(p) || !PART_TAGS.has(p[0] as string)) return void E('part-shape', `unknown part ${JSON.stringify(p)?.slice(0, 40)}`, at)
    const paths: string[] = []
    switch (p[0]) {
      case 'f':
        if (!isArtColour(p[1])) E('colour', `"${String(p[1])}" is not an allowed color (PaintKey, key~, acc, sil)`, at)
        if (p[1] === 'acc' && !hasAccent && kind === 'icon') W('accent', "'acc' part but the def has no `accent` (falls back to the highlighter)", at)
        paths.push(p[2])
        if (p[3] !== undefined && !(p[3] >= 0 && p[3] <= 3)) E('mis', 'fill misregistration multiplier must be 0..3', at)
        break
      case 's':
        paths.push(p[1])
        break
      case 'c':
        if (!isArtColour(p[1]) || p[1] === 'sil') E('colour', `"${String(p[1])}" is not an allowed stroke color`, at)
        paths.push(p[2])
        break
      case 'h':
        paths.push(p[1])
        break
      case 'd': {
        const [, x, y, r] = p
        if (![x, y].every((v) => typeof v === 'number' && Number.isFinite(v))) E('part-shape', 'dot needs numeric x y', at)
        else if (area && (x < area[0] || x > area[2] || y < area[1] || y > area[3])) E('bounds', `dot (${x}, ${y}) is outside the usable area ${area[0]},${area[1]}..${area[2]},${area[3]}`, at)
        if (r !== undefined && !(r >= 0.6 && r <= (tier === 'micro' ? 8 : 6))) W('dot-radius', `dot radius ${r} is outside 0.6..${tier === 'micro' ? 8 : 6} grid units`, at)
        return
      }
      case 't': {
        const [, txt, x, y, size] = p
        const font = p[6] ?? 'hand'
        if (font !== 'hand' && font !== 'type') E('text', `unknown lettering font "${String(font)}" (hand | type)`, at)
        else if (glyph) for (const ch of String(txt).toUpperCase()) if (ch !== ' ' && glyph(font, ch) === false) E('text', `no glyph for "${ch}" in the ${font} lettering`, at)
        if (![x, y, size].every((v) => typeof v === 'number' && Number.isFinite(v))) E('part-shape', 'text needs numeric x y size', at)
        if (p[5] !== undefined && !isArtColour(p[5])) E('colour', `"${String(p[5])}" is not an allowed color`, at)
        return
      }
    }
    const wm = widthOf(p)
    if (wm !== undefined) {
      const lo = kind === 'icon' && tier !== 'hi' ? 0.6 : 0.45
      const hi = tier === 'micro' ? 1.8 : kind === 'icon' ? 1.4 : 1.5
      if (!(wm >= 0.4 && wm <= 1.8)) E('width', `widthMul ${wm} is outside 0.4..1.8`, at)
      else if (wm < lo || wm > hi) W('width', `widthMul ${wm} is outside ${lo}..${hi} for ${kind} ${tier}`, at)
    }
    for (const d of paths) {
      const r = checkPath(d)
      for (const m of r.errors) E('path', m, at)
      for (const m of r.warnings) W('path-style', m, at)
      if (!r.errors.length && r.bbox && area && !(p[0] === 'f' && p[1] === 'sil')) {
        const [x0, y0, x1, y1] = r.bbox
        const slack = 0.5
        if (x0 < area[0] - slack || y0 < area[1] - slack || x1 > area[2] + slack || y1 > area[3] + slack) {
          E('bounds', `path extent ${x0.toFixed(1)},${y0.toFixed(1)}..${x1.toFixed(1)},${y1.toFixed(1)} leaves the usable area ${area[0]},${area[1]}..${area[2]},${area[3]}`, at)
        }
      }
    }
  })
  return out
}

export function validateArt(def: ArtDef, o: { id?: string; kind?: ArtKind; glyph?: GlyphLookup } = {}): Problem[] {
  const out: Problem[] = []
  const kind = o.kind ?? kindOfDef(def)
  const g = def.grid
  const okGrid = g === 24 || g === 64 || (Array.isArray(g) && g.length === 2 && g.every((v) => Number.isFinite(v) && v >= 8 && v <= 512))
  if (!okGrid) out.push({ level: 'error', code: 'grid', msg: `grid must be 24, 64 or [w, h] (got ${JSON.stringify(g)})` })
  if (!Array.isArray(def.parts) || !def.parts.length) out.push({ level: 'error', code: 'parts', msg: 'a definition needs at least one part' })
  if (def.accent !== undefined && !([...ACCENT_KEYS, 'hi', 'kraft'] as string[]).includes(def.accent)) out.push({ level: 'error', code: 'accent', msg: `accent "${String(def.accent)}" is not a stationery accent, "hi" or "kraft"` })
  if (def.nibK !== undefined && !(def.nibK >= 0.02 && def.nibK <= 0.14)) out.push({ level: 'error', code: 'nibK', msg: 'nibK must be 0.02..0.14' })
  if (def.tags !== undefined && (!Array.isArray(def.tags) || def.tags.some((t) => typeof t !== 'string' || !t))) out.push({ level: 'error', code: 'tags', msg: 'tags must be non-empty strings' })
  const b = BUDGET[kind as keyof typeof BUDGET]
  const tiers: Array<['parts' | 'small' | 'micro' | 'hi', readonly Part[] | undefined]> = [['parts', def.parts], ['small', def.small], ['micro', def.micro], ['hi', def.hi]]
  for (const [name, list] of tiers) {
    if (!list) continue
    if (!Array.isArray(list)) {
      out.push({ level: 'error', code: 'parts', msg: `${name} must be an array of parts` })
      continue
    }
    out.push(...validateParts(list, kind, name, def.accent !== undefined, o.glyph))
    const blots = list.filter((p) => p[0] === 'd').length
    const drawn = list.length - blots
    if (b && drawn > b[name]) out.push({ level: 'error', code: 'budget', msg: `${name} has ${drawn} fills / strokes; the ${kind} budget is ${b[name]} (put several strokes in one path with M)`, at: name })
    if (blots > 8) out.push({ level: 'error', code: 'budget', msg: `${name} has ${blots} blots; at most 8`, at: name })
  }
  if (def.small && def.parts && JSON.stringify(def.small) === JSON.stringify(def.parts)) out.push({ level: 'warn', code: 'small-copy', msg: '`small` is identical to the master: redraw it (bigger silhouette, fewer details, heavier strokes)' })
  return out
}

import { PathWriter } from '@/lib/ink/geom'
import type { Q } from '@/lib/ink/paint'
import type { Rng } from '@/lib/ink/rng'
import { GLYPH_FONTS, type GlyphFont } from '@/lib/ink/art/glyphs'
import type { LetterFont } from '@/lib/ink/art/types'

type Cmd = readonly [string, ...number[]]
const parsed = new Map<string, Cmd[]>()

function commands(font: LetterFont, ch: string): Cmd[] {
  const key = font + ch
  let c = parsed.get(key)
  if (c) return c
  c = []
  const d = GLYPH_FONTS[font].d[ch] ?? ''
  for (const m of d.matchAll(/([MLQZ])([^MLQZ]*)/g)) {
    const nums = m[2].trim() ? m[2].trim().split(/[ ,]+/).map(Number) : []
    c.push([m[1], ...nums] as unknown as Cmd)
  }
  parsed.set(key, c)
  return c
}

const upper = (s: string): string => s.toUpperCase()

const FIT = 0.8

export const hasGlyph = (font: string, ch: string): boolean => {
  const F = (GLYPH_FONTS as Record<string, GlyphFont>)[font]
  return !!F && (ch === ' ' || !!F.d[ch])
}

export function measureText(font: LetterFont, text: string, size: number, spacing = 0): number {
  const F = GLYPH_FONTS[font]
  let w = 0
  const t = upper(text)
  for (let i = 0; i < t.length; i++) w += ((F.adv[t[i]] ?? F.adv[' '] ?? 300) / 1000) * size * FIT + (i < t.length - 1 ? spacing : 0)
  return w
}

export const capHeight = (font: LetterFont, size: number): number => (GLYPH_FONTS[font].cap / 1000) * size * FIT

export interface TextOpts {
  font?: LetterFont
  anchor?: 'start' | 'middle' | 'end'
  spacing?: number
  jitter?: number
  rot?: number
  squeeze?: number
  q?: Q
}

export interface TextPath {
  d: string
  width: number
  bbox: [number, number, number, number]
}

export function textPath(text: string, x: number, y: number, em: number, rng: Rng, o: TextOpts = {}): TextPath {
  const font = o.font ?? 'hand'
  const F = GLYPH_FONTS[font]
  const t = upper(text)
  const sq = o.squeeze ?? 1
  const size = em * FIT
  const s = size / 1000
  const spacing = o.spacing ?? 0
  const jit = (o.jitter ?? 0) * 0.3
  const total = measureText(font, t, em, spacing) * sq
  const x0 = o.anchor === 'start' ? x : o.anchor === 'end' ? x - total : x - total / 2
  const w = new PathWriter(o.q ?? 10)
  const ampY = 0.045 * size * jit
  const ph = rng() * 6.28, ph2 = rng() * 6.28
  const rot0 = ((o.rot ?? 0) * Math.PI) / 180
  const cr = Math.cos(rot0), sr = Math.sin(rot0)
  let pen = 0
  const bb: [number, number, number, number] = [Infinity, Infinity, -Infinity, -Infinity]
  for (let i = 0; i < t.length; i++) {
    const ch = t[i]
    const adv = ((F.adv[ch] ?? F.adv[' '] ?? 300) / 1000) * size * sq
    const cmds = commands(font, ch)
    if (cmds.length) {
      const dy = ampY * (0.6 * Math.sin(i * 0.9 + ph) + 0.4 * Math.sin(i * 2.3 + ph2)) + rng.gauss(0, ampY * 0.3)
      const lean = (rng.gauss(0, 1.5) * jit * Math.PI) / 180
      const gx = pen + adv / 2, gy = 0
      const cl = Math.cos(lean), sl = Math.sin(lean)
      const tr = (px: number, py: number): [number, number] => {
        let X = px * s * sq + pen, Y = py * s + dy
        const rx = X - gx, ry = Y - gy
        X = gx + rx * cl - ry * sl
        Y = gy + rx * sl + ry * cl
        const ax = x0 - x + X
        return [x + ax * cr - Y * sr, y + ax * sr + Y * cr]
      }
      for (const c of cmds) {
        const k = c[0]
        if (k === 'M') { const [a, b] = tr(c[1], c[2]); w.M(a, b); grow(bb, a, b) }
        else if (k === 'L') { const [a, b] = tr(c[1], c[2]); w.L(a, b); grow(bb, a, b) }
        else if (k === 'Q') { const [a, b] = tr(c[1], c[2]); const [e, f] = tr(c[3], c[4]); w.Q(a, b, e, f); grow(bb, e, f) }
        else if (k === 'Z') w.Z()
      }
    }
    pen += adv + spacing
  }
  return { d: w.d, width: total, bbox: bb[0] === Infinity ? [x, y, x, y] : bb }
}

function grow(b: [number, number, number, number], x: number, y: number): void {
  if (x < b[0]) b[0] = x
  if (y < b[1]) b[1] = y
  if (x > b[2]) b[2] = x
  if (y > b[3]) b[3] = y
}

import { dieCut, type DieCutResult } from '@/lib/ink/art-draw'
import type { ArtDef } from '@/lib/ink/art/types'
import { clamp } from '@/lib/ink/rng'

export interface MascotDrawOpts {
  tier?: 'lo' | 'hi'
  idPrefix?: string
  border?: number
  shadow?: boolean
}

export const mascotVariant = (size: number): 'micro' | 'small' | 'master' | 'hi' => (size < 28 ? 'micro' : size < 56 ? 'small' : size < 140 ? 'master' : 'hi')

export function drawMascot(def: ArtDef, size: number, seed: string | number, o: MascotDrawOpts = {}): DieCutResult {
  const px = Math.max(16, Math.round(size))
  const border = o.border ?? (px < 28 ? 1 : clamp(px * 0.065, 1.8, 6.5))
  const art = Math.max(8, px - 2 * Math.ceil(border + 2))
  const nib = clamp(art * (def.nibK ?? 0.05), 1.05, 4.6)
  return dieCut(def, art, seed, { border, nib, tier: o.tier ?? 'lo', variant: mascotVariant(px), idPrefix: o.idPrefix, shadow: o.shadow, silAll: false })
}

import { Ink, type InkResult } from '@/lib/ink/builder'
import { area, densifyClosed, ellipsePoly, polyPath, roundRectPoly } from '@/lib/ink/geom'
import type { PaintKey } from '@/lib/ink/paint'
import { clamp, type Rng } from '@/lib/ink/rng'
import type { Pt } from '@/lib/ink/types'
import { measureText, textPath } from '@/lib/ink/art/glyph-text'
import type { StampGen } from '@/lib/ink/art/types'

export interface StampOpts extends Partial<Omit<StampGen, 'gen' | 'text' | 'shape' | 'kind'>> {
  seed?: string | number
  grain?: boolean
}

const INK: Record<NonNullable<StampGen['ink']>, PaintKey> = { red: 'red', 'ink-you': 'ink-you', green: 'green', ink: 'ink' }

const flip = (pts: Pt[]): Pt[] => (area(pts) > 0 ? pts.slice().reverse() : pts)

function ring(outer: Pt[], inner: Pt[]): string {
  const o = area(outer) < 0 ? outer.slice().reverse() : outer
  const i = area(inner) > 0 ? inner.slice().reverse() : inner
  return polyPath(o, 10) + polyPath(i, 10)
}

function star(cx: number, cy: number, ro: number, ri: number, rot = -90): Pt[] {
  const p: Pt[] = []
  for (let i = 0; i < 10; i++) {
    const a = ((rot + i * 36) * Math.PI) / 180
    const r = i % 2 ? ri : ro
    p.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r])
  }
  return p
}

function dashes(poly: Pt[], len: number, gap: number, w: number, rng: Rng): string {
  let d = ''
  const m = poly.length
  let carry = 0
  let on = true
  let left = len
  for (let i = 0; i < m; i++) {
    const a = poly[i], b = poly[(i + 1) % m]
    const L = Math.hypot(b[0] - a[0], b[1] - a[1])
    const ux = (b[0] - a[0]) / (L || 1), uy = (b[1] - a[1]) / (L || 1)
    let s = carry
    while (s < L) {
      const step = Math.min(left, L - s)
      if (on && step > 0.5) {
        const p0: Pt = [a[0] + ux * s, a[1] + uy * s], p1: Pt = [a[0] + ux * (s + step), a[1] + uy * (s + step)]
        const nx = -uy * w * 0.5, ny = ux * w * 0.5
        d += polyPath([[p0[0] + nx, p0[1] + ny], [p1[0] + nx, p1[1] + ny], [p1[0] - nx, p1[1] - ny], [p0[0] - nx, p0[1] - ny]], 10)
      }
      s += step
      left -= step
      if (left <= 0.01) {
        on = !on
        left = (on ? len : gap) * (0.85 + rng() * 0.3)
      }
    }
    carry = 0
  }
  return d
}

function cleanRect(x: number, y: number, w: number, h: number, r: number): Pt[] {
  return densifyClosed(roundRectPoly(x, y, w, h, r, 5), 5)
}

export function stamp(text: string, shape: StampGen['shape'], o: StampOpts = {}): InkResult {
  const key = INK[o.ink ?? 'red']
  const seed = `stamp:${o.seed ?? text}:${shape}`
  const ink = new Ink(seed, { tier: 'lo', grain: o.grain })
  const rng = ink.rng.fork('stamp')
  const round = shape === 'round' || shape === 'burst'
  const W = o.w ?? (round ? 96 : shape === 'void' ? 160 : 160)
  const H = o.h ?? (round ? W : shape === 'void' ? 64 : 56)
  const tilt = o.tilt ?? (rng.range(-5, 5))
  const cx = W / 2, cy = H / 2
  const TXT = text.toUpperCase()

  const impression = (r: Rng, alpha: number): void => {
    let d = ''
    const outerW = clamp(H * 0.045, 2, 3), innerW = 1.1
    if (shape === 'rect') {
      const a = cleanRect(0, 0, W, H, 5)
      const b = cleanRect(outerW, outerW, W - 2 * outerW, H - 2 * outerW, 3.4)
      d += ring(a, b)
      const gap = 3.1
      const c = cleanRect(outerW + gap, outerW + gap, W - 2 * (outerW + gap), H - 2 * (outerW + gap), 2.4)
      const e = cleanRect(outerW + gap + innerW, outerW + gap + innerW, W - 2 * (outerW + gap + innerW), H - 2 * (outerW + gap + innerW), 2)
      d += o.dashed ? dashes(c, 5.5, 3.2, innerW + 0.3, r.fork('dash')) : ring(c, e)
      const innerH = H - 2 * (outerW + gap + innerW)
      const innerW2 = W - 2 * (outerW + gap + innerW) - 10
      const sub = o.sub
      let em = Math.min(innerH * (sub ? 0.5 : 0.62), 38)
      const spacing = clamp(em * 0.08, 1, 3.4)
      const fit = innerW2 / Math.max(1, measureText('type', TXT, 1, 0) + (TXT.length - 1) * (spacing / em))
      em = Math.min(em, fit)
      const cap = 0.68 * em
      const ty = sub ? cy - innerH * 0.06 + cap / 2 - 1 : cy + cap / 2
      const t = textPath(TXT, cx, ty, em, r.fork('t'), { font: 'type', spacing: (spacing * em) / Math.max(em, 1) * 0.9, jitter: 0.25 })
      d += t.d
      if (sub) {
        const sm = clamp(innerH * 0.2, 6, 10)
        const st = textPath(sub.toUpperCase(), cx, cy + innerH * 0.34, sm, r.fork('s'), { font: 'type', spacing: 1.2, jitter: 0.2 })
        d += st.d
      }
    } else if (shape === 'round' || shape === 'burst') {
      const R = W / 2
      if (shape === 'burst') {
        const pts: Pt[] = []
        for (let i = 0; i < 24; i++) {
          const a = (i / 24) * Math.PI * 2 - Math.PI / 2
          const rr = i % 2 ? R * 0.82 : R - 1
          pts.push([cx + Math.cos(a) * rr, cy + Math.sin(a) * rr])
        }
        d += ring(pts, densifyClosed(ellipsePoly(cx, cy, R * 0.76, R * 0.76, 48), 4))
        d += ring(densifyClosed(ellipsePoly(cx, cy, R * 0.66, R * 0.66, 48), 4), densifyClosed(ellipsePoly(cx, cy, R * 0.66 - 1.1, R * 0.66 - 1.1, 48), 4))
      } else {
        const a = densifyClosed(ellipsePoly(cx, cy, R - 0.5, R - 0.5, 60), 5)
        const b = densifyClosed(ellipsePoly(cx, cy, R - 0.5 - 2.6, R - 0.5 - 2.6, 60), 5)
        d += ring(a, b)
        const rin = R * 0.63
        d += ring(densifyClosed(ellipsePoly(cx, cy, rin, rin, 48), 4), densifyClosed(ellipsePoly(cx, cy, rin - 1.1, rin - 1.1, 48), 4))
      }
      const inner = shape === 'burst' ? R * 0.6 : R * 0.62
      let em = Math.min(W * 0.3, 40)
      const fit = (inner * 1.78) / Math.max(0.5, measureText('type', TXT, 1, 0) + TXT.length * 0.06)
      em = Math.min(em, fit)
      const cap = 0.68 * em
      const t = textPath(TXT, cx, cy + cap / 2 - (o.sub ? 1.5 : 0), em, r.fork('t'), { font: 'type', spacing: em * 0.06, jitter: 0.25 })
      d += t.d
      if (o.sub) d += textPath(o.sub.toUpperCase(), cx, cy + cap / 2 + em * 0.42, Math.max(5.5, em * 0.28), r.fork('s'), { font: 'type', spacing: 0.8, jitter: 0.2 }).d
      const ns = o.stars ?? (shape === 'round' ? 2 : 0)
      for (let i = 0; i < ns; i++) {
        const sx = cx + (i === 0 ? -1 : 1) * inner * 0.68
        d += polyPath(star(sx, cy - cap * 1.05 - 3, 2.6, 1.1, -90), 10)
      }
      if (shape === 'round') {
        const rim = o.ring ?? ''
        const chars = Array.from(rim.toUpperCase())
        if (chars.length) {
          const rr = R - 2.6 - 3.4 - 2
          const span = chars.length >= 12 ? 300 : chars.length * 26
          const sz = clamp((rr * ((span * Math.PI) / 180)) / (chars.length * 0.86), 5.2, 10)
          chars.forEach((ch, i) => {
            if (ch === ' ') return
            const ang = -90 - span / 2 + ((i + 0.5) / chars.length) * span
            const A = (ang * Math.PI) / 180
            d += textPath(ch, cx + Math.cos(A) * rr, cy + Math.sin(A) * rr, sz, r.fork(`ch${i}`), { font: 'type', rot: ang + 90, jitter: 0.1 }).d
          })
        }
      }
    } else {
      const em = Math.min(H * 0.86, (W * 0.86) / Math.max(1, measureText('type', TXT, 1, 0)))
      const t = textPath(TXT, cx, cy + em * 0.34, em, r.fork('t'), { font: 'type', spacing: em * 0.04, jitter: 0.35, rot: -8 })
      d += t.d
      const bar = densifyClosed([[cx - W * 0.44, cy + 3.5], [cx + W * 0.44, cy - 3.2], [cx + W * 0.44, cy - 0.2], [cx - W * 0.44, cy + 6.4]], 5)
      d += polyPath(flip(bar), 10)
    }
    ink.flat('text', d, key, alpha, { bbox: [-6, -6, W + 6, H + 6] })
  }

  ink.group({ transform: `rotate(${(tilt).toFixed(2)} ${cx.toFixed(1)} ${cy.toFixed(1)})` }, () => {
    if (o.ghost) ink.group({ transform: `translate(${(1.6).toFixed(1)} ${(-1.3).toFixed(1)}) rotate(0.8 ${cx.toFixed(1)} ${cy.toFixed(1)})` }, () => impression(rng.fork('ghost'), 0.2), 'stamp')
    impression(rng.fork('main'), 0.92)
  }, 'stamp')
  return ink.toSvg({ w: W, h: H, pad: 10 })
}

import type { PaintKey } from '@/lib/ink/paint'
import type { Accent } from '@/lib/ink/types'
import { validateArt, type Problem } from '@/lib/ink/art/dsl'

export type ArtKind = 'icon' | 'doodle' | 'sticker' | 'mascot' | 'prop' | 'scene'

export type ArtColour = Exclude<PaintKey, 'current'> | `${Exclude<PaintKey, 'current'>}~` | 'acc' | 'sil'

export type LetterFont = 'hand' | 'type'

export interface Hand {
  start?: 'pool' | 'soft'
  end?: 'pool' | 'flick' | 'soft'
  taper?: number
}

export type Part =
  | readonly ['f', ArtColour, string, number?]
  | readonly ['s', string, number?, Hand?]
  | readonly ['c', ArtColour, string, number?, Hand?]
  | readonly ['d', number, number, number?]
  | readonly ['h', string, number?]
  | readonly ['t', string, number, number, number, ArtColour?, LetterFont?]

export type ArtAccent = Accent | 'hi' | 'kraft'

export interface ArtDef {
  grid: 24 | 64 | readonly [number, number]
  parts: readonly Part[]
  small?: readonly Part[]
  micro?: readonly Part[]
  hi?: readonly Part[]
  accent?: ArtAccent
  nibK?: number
  tags?: readonly string[]
  shade?: boolean
  tilt?: number
  rtl?: 'flip'
  mirror?: boolean
  kind?: ArtKind
}

export interface BadgeGen {
  gen: 'badge'
  text: string
  shape?: 'scallop' | 'starburst' | 'rosette' | 'banner' | 'tag' | 'ticket' | 'plate' | 'shield' | 'medal'
  color?: Exclude<PaintKey, 'current'>
  sub?: string
  bumps?: number
  amp?: number
  deco?: 'tick' | 'star' | 'sparkle' | 'swoosh' | 'percent'
  textColor?: Exclude<PaintKey, 'current'>
  tilt?: number
  tags?: readonly string[]
  kind?: ArtKind
}

export interface StampGen {
  gen: 'stamp'
  text: string
  shape: 'rect' | 'round' | 'burst' | 'void'
  sub?: string
  ring?: string
  ink?: 'red' | 'ink-you' | 'green' | 'ink'
  w?: number
  h?: number
  tilt?: number
  ghost?: boolean
  dashed?: boolean
  wear?: number
  stars?: number
  tags?: readonly string[]
  kind?: ArtKind
}

export type StickerDef = ArtDef | BadgeGen | StampGen

declare const process: { env?: { NODE_ENV?: string } } | undefined

const isDev = (): boolean => {
  const env = (import.meta as unknown as { env?: { DEV?: boolean } }).env
  if (env && typeof env.DEV === 'boolean') return env.DEV
  return typeof process !== 'undefined' && process?.env?.NODE_ENV !== 'production'
}

function check(kind: ArtKind, id: string, def: ArtDef): void {
  if (!isDev()) return
  const errors = validateArt(def, { id, kind }).filter((p: Problem) => p.level === 'error')
  if (errors.length) throw new Error(`ink art: ${kind} "${id}": ${errors.map((e) => `${e.at ? e.at + ' ' : ''}${e.msg}`).join('; ')}`)
}

function make<T extends Record<string, ArtDef>>(kind: ArtKind, map: T): T {
  const out: Record<string, ArtDef> = {}
  for (const id of Object.keys(map)) {
    const def = { ...map[id], kind }
    check(kind, id, def)
    out[id] = def
  }
  return out as T
}

export const defineIcons = <const T extends Record<string, ArtDef>>(map: T): T => make('icon', map)
export const defineDoodles = <const T extends Record<string, ArtDef>>(map: T): T => make('doodle', map)
export const defineMascot = <const T extends Record<string, ArtDef>>(map: T): T => make('mascot', map)
export const defineProps = <const T extends Record<string, ArtDef>>(map: T): T => make('prop', map)
export function defineStickers<const T extends Record<string, StickerDef>>(map: T): T {
  const out: Record<string, StickerDef> = {}
  for (const id of Object.keys(map)) {
    const def = map[id]
    if ('gen' in def) out[id] = { ...def, kind: 'sticker' }
    else {
      const d = { ...def, kind: 'sticker' as const }
      check('sticker', id, d)
      out[id] = d
    }
  }
  return out as T
}

export const defineIcon = (def: ArtDef): ArtDef => make('icon', { def }).def
export const defineDoodle = (def: ArtDef): ArtDef => make('doodle', { def }).def
export const defineSticker = (def: StickerDef): StickerDef => defineStickers({ def }).def

export const isGen = (d: StickerDef): d is BadgeGen | StampGen => 'gen' in d

import { Ink, type InkResult, type Knobs } from '@/lib/ink/builder'
import { flatFill } from '@/lib/ink/fills'
import { PathWriter, TIERS, smoothClosed } from '@/lib/ink/geom'
import { noise1 } from '@/lib/ink/noise'
import { n, type PaintKey } from '@/lib/ink/paint'
import { pen as penSpec } from '@/lib/ink/pens'
import { clamp, hashSeed, type Rng } from '@/lib/ink/rng'
import type { BBox, Pt, Tier } from '@/lib/ink/types'
import { parsePath, polygonsOf, kindOfDef, type Sub } from '@/lib/ink/art/dsl'
import { capHeight, textPath } from '@/lib/ink/art/glyph-text'
import { isGen, type ArtAccent, type ArtColour, type ArtDef, type ArtKind, type Hand, type Part, type StickerDef } from '@/lib/ink/art/types'

import { badgeSkeleton } from '@/lib/ink/art/badge-gen'
import { stamp } from '@/lib/ink/art/rubber-stamp'
export { badgeSkeleton }
export type { BadgeOpts } from '@/lib/ink/art/badge-gen'
export { stamp }
export type { StampOpts } from '@/lib/ink/art/rubber-stamp'
export { measureText, textPath } from '@/lib/ink/art/glyph-text'
export type { ArtDef, ArtKind, Part } from '@/lib/ink/art/types'

export type Variant = 'micro' | 'small' | 'master' | 'hi'

export function variantFor(kind: ArtKind, size: number): Variant {
  switch (kind) {
    case 'icon':
      return size <= 13 ? 'micro' : size <= 19 ? 'small' : size <= 40 ? 'master' : 'hi'
    case 'doodle':
      return size < 72 ? 'small' : size < 120 ? 'master' : 'hi'
    case 'sticker':
      return size < 80 ? 'small' : size < 120 ? 'master' : 'hi'
    case 'mascot':
      return size < 40 ? 'micro' : size < 72 ? 'small' : size < 140 ? 'master' : 'hi'
    default:
      return 'master'
  }
}

export function partsFor(def: ArtDef, variant: Variant): readonly Part[] {
  if (variant === 'micro') return def.micro ?? def.small ?? def.parts
  if (variant === 'small') return def.small ?? def.parts
  if (variant === 'hi' && def.hi) return [...def.parts, ...def.hi]
  return def.parts
}

const NIB: Record<ArtKind, { k: number; min: number; max: number }> = {
  icon: { k: 0.068, min: 1.45, max: 3.4 },
  doodle: { k: 0.05, min: 1.7, max: 5.2 },
  sticker: { k: 0.055, min: 1.8, max: 5.2 },
  mascot: { k: 0.05, min: 1.6, max: 5 },
  prop: { k: 0.05, min: 1.6, max: 5 },
  scene: { k: 0.04, min: 1.4, max: 4 },
}

export interface DrawOpts {
  tone?: 'ui' | 'doodle'
  tier?: Tier
  ink?: PaintKey
  accent?: ArtAccent
  kind?: ArtKind
  variant?: Variant
  nib?: number
  shade?: boolean
  grain?: boolean
  calm?: boolean
  knobs?: Partial<Knobs>
  silAll?: boolean
  pad?: number
}

export interface Silhouette {
  fills: string[]
  lines: string[]
  pts: Pt[]
  W: number
}

export interface SkeletonResult extends InkResult {
  variant: Variant
  kind: ArtKind
  nib: number
  k: number
  silhouette: Silhouette
}

function wander(pts: Pt[], rng: Rng, k: number, amp: number): Pt[] {
  let L = 20
  for (let i = 1; i < pts.length; i++) L += Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]) * k
  const nx = noise1(rng.fork('x'), L, 7 * k), ny = noise1(rng.fork('y'), L, 7 * k)
  const ox = rng.gauss(0, amp * 0.6), oy = rng.gauss(0, amp * 0.6)
  let s = 0
  return pts.map(([x, y], i) => {
    if (i) s += Math.hypot(x - pts[i - 1][0], y - pts[i - 1][1]) * k
    return [x * k + ox + nx(s) * amp, y * k + oy + ny(s) * amp]
  })
}

function roundCorners(pts: Pt[], anchor: boolean[], r: number): Pt[] {
  if (pts.length < 3 || r < 0.2) return pts
  const out: Pt[] = [pts[0]]
  for (let i = 1; i < pts.length - 1; i++) {
    const a = pts[i - 1], b = pts[i], c = pts[i + 1]
    if (!anchor[i]) {
      out.push(b)
      continue
    }
    const l1 = Math.hypot(b[0] - a[0], b[1] - a[1]), l2 = Math.hypot(c[0] - b[0], c[1] - b[1])
    if (l1 < r * 1.6 || l2 < r * 1.6) {
      out.push(b)
      continue
    }
    const cos = ((b[0] - a[0]) * (c[0] - b[0]) + (b[1] - a[1]) * (c[1] - b[1])) / (l1 * l2)
    if (cos > 0.85) {
      out.push(b)
      continue
    }
    const rr = Math.min(r, l1 * 0.4, l2 * 0.4)
    const p1: Pt = [b[0] + ((a[0] - b[0]) / l1) * rr, b[1] + ((a[1] - b[1]) / l1) * rr]
    const p2: Pt = [b[0] + ((c[0] - b[0]) / l2) * rr, b[1] + ((c[1] - b[1]) / l2) * rr]
    for (let t = 0; t <= 4; t++) {
      const u = t / 4, v = 1 - u
      out.push([v * v * p1[0] + 2 * u * v * b[0] + u * u * p2[0], v * v * p1[1] + 2 * u * v * b[1] + u * u * p2[1]])
    }
  }
  out.push(pts[pts.length - 1])
  return out
}

const openPath = (pts: Pt[]): string => {
  const w = new PathWriter(10)
  pts.forEach((p, i) => (i ? w.L(p[0], p[1]) : w.M(p[0], p[1])))
  return w.d
}

const WASH_ALPHA = 0.42
const DARK: ReadonlySet<string> = new Set(['ink', 'ink-soft', 'ink-you', 'pencil', 'red', 'green', 'focus'])

export function paintSkeleton(ink: Ink, def: ArtDef, size: number, o: DrawOpts = {}, origin: Pt = [0, 0]): { silhouette: Silhouette; variant: Variant; kind: ArtKind; nib: number; k: number; w: number; h: number } {
  const kind = o.kind ?? kindOfDef(def)
  const variant = o.variant ?? variantFor(kind, size)
  const parts = partsFor(def, variant)
  const [gw, gh] = def.grid === 24 || def.grid === 64 ? [def.grid, def.grid] : def.grid
  const k = size / Math.max(gw, gh)
  const tone = o.tone ?? (kind === 'icon' ? 'ui' : 'doodle')
  const nibSpec = NIB[kind]
  const nib = o.nib ?? clamp(size * (def.nibK ?? nibSpec.k), nibSpec.min, nibSpec.max)
  const inkKey: PaintKey = o.ink ?? (tone === 'ui' ? 'current' : 'ink')
  const accent = (o.accent ?? def.accent ?? 'hi') as PaintKey
  const icon = kind === 'icon'
  const sticker = kind === 'sticker'
  const sPen = icon ? penSpec('ink.fine', { step: size <= 40 ? 0.7 : 1.2 }) : penSpec('ink')
  const penW = sPen.W
  const wob = 0.12
  const amp = clamp(size * 0.002, 0.04, 0.22)
  const root = ink.rng.fork('skel')
  const sil: Silhouette = { fills: [], lines: [], pts: [], W: nib }
  const seenFills = new Set<string>()
  let lastFill = ''
  const off = (ps: Pt[]): Pt[] => (origin[0] || origin[1] ? ps.map(([x, y]) => [x + origin[0], y + origin[1]] as Pt) : ps)
  const tc = Math.cos(((def.tilt ?? 0) * Math.PI) / 180), ts = Math.sin(((def.tilt ?? 0) * Math.PI) / 180)
  const turn = def.tilt
    ? (ps: Pt[]): Pt[] => ps.map(([x, y]) => [gw / 2 + (x - gw / 2) * tc - (y - gh) * ts, gh + (x - gw / 2) * ts + (y - gh) * tc] as Pt)
    : (ps: Pt[]): Pt[] => ps
  const fillAlpha = sticker ? 1 : icon ? 0.9 : 0.95
  const fillMaterial = sticker ? 'wash' : 'marker'
  const cornerR = nib * 0.55

  parts.forEach((p, i) => {
    const pr = root.fork('p' + i)
    const tag = p[0]
    if (tag === 'f') {
      const colour = p[1]
      const isSil = colour === 'sil'
      if (colour === 'acc' && tone === 'ui') return
      polygonsOf(p[2], { rnd: pr }).forEach((poly, pi) => {
        const px = off(wander(turn(poly), pr.fork('w' + pi), k, amp))
        sil.fills.push(smoothPath(px))
        for (let q = 0; q < px.length; q += 2) sil.pts.push(px[q])
        if (isSil) return
        const wash_ = colour === 'acc' || colour.endsWith('~')
        const key = (colour === 'acc' ? accent : wash_ ? colour.slice(0, -1) : colour) as PaintKey
        if (wash_) {
          flatFill(ink, px, key, WASH_ALPHA, 'marker')
        } else {
          const run = (): void => flatFill(ink, px, key, fillAlpha, sticker ? 'wash' : DARK.has(key) ? 'text' : fillMaterial)
          if (sticker && seenFills.has(key) && lastFill !== key) ink.group({}, run, 'wash')
          else run()
          seenFills.add(key)
          lastFill = key
        }
      })
    } else if (tag === 's' || tag === 'c') {
      const path = tag === 's' ? p[1] : p[2]
      const wm = (tag === 's' ? p[2] : p[3]) ?? 1
      const hand: Hand = (tag === 's' ? p[3] : p[4]) ?? {}
      const colour: ArtColour | 'current' = tag === 's' ? inkKey : p[1]
      const washStroke = colour.endsWith('~')
      const key = (colour === 'acc' ? accent : washStroke ? colour.slice(0, -1) : colour) as PaintKey
      if (colour === 'acc' && tone === 'ui') return
      parsePath(path, { step: Math.max(0.35, 0.9 / k), rnd: pr }).forEach((sub: Sub, j) => {
        if (sub.pts.length < 2) return
        const r = pr.fork('s' + j)
        const px = off(wander(turn(sub.pts), r.fork('w'), k, amp))
        if (tag === 's' || o.silAll) {
          sil.lines.push(openPath(px))
          for (let q = 0; q < px.length; q += 3) sil.pts.push(px[q])
        }
        const pts = roundCorners(px, sub.anchor, cornerR)
        const brush = tag === 'c'
        const w = (nib * wm * (brush ? 1.5 : 1)) / penW
        ink.stroke(pts, sPen, {
          poly: true,
          color: key,
          width: w,
          alpha: washStroke ? 0.5 : brush ? 0.95 : 1,
          wobble: wob,
          speed: 1,
          dry: 0,
          start: hand.start ?? 'soft',
          end: hand.end ?? 'soft',
          press: hand.taper ? (t: number) => Math.max(0.3, 1 + hand.taper! * (0.5 - t) * 1.5) : undefined,
        })
      })
    } else if (tag === 'd') {
      const rr = Math.max((p[3] ?? 1.4) * k, nib * 0.62)
      const [tx, ty] = turn([[p[1], p[2]]])[0]
      const x = tx * k + origin[0], y = ty * k + origin[1]
      sil.lines.push(openPath([[x, y], [x + 0.01, y]]))
      sil.pts.push([x, y])
      ink.dot(x, y, rr, sPen, { color: inkKey })
    } else if (tag === 't') {
      const [, text, x, y, em, colour, font] = p
      const px = em * k
      const key = (colour ? (colour === 'acc' ? accent : colour.endsWith('~') ? colour.slice(0, -1) : colour) : inkKey) as PaintKey
      const t = textPath(text, x * k + origin[0], y * k + origin[1], px, pr.fork('t'), { font: font ?? 'hand', jitter: 0 })
      ink.flat('text', t.d, key, 1, { bbox: t.bbox })
      const cap = capHeight(font ?? 'hand', px)
      sil.lines.push(openPath([[t.bbox[0], y * k + origin[1] - cap * 0.5], [t.bbox[2], y * k + origin[1] - cap * 0.5]]))
      sil.pts.push([t.bbox[0], t.bbox[1]], [t.bbox[2], t.bbox[3]])
    }
  })

  return { silhouette: sil, variant, kind, nib, k, w: gw * k, h: gh * k }
}

function smoothPath(px: Pt[]): string {
  return smoothClosed(px, TIERS.lo)
}

export function drawSkeleton(def: ArtDef, size: number, seed: string | number, o: DrawOpts = {}): SkeletonResult {
  const kind = o.kind ?? kindOfDef(def)
  const tier: Tier = o.tier ?? (size >= 128 && (kind === 'doodle' || kind === 'mascot') ? 'hi' : 'lo')
  const ink = new Ink(`${seed}`, { tier, grain: o.grain, calm: o.calm, knobs: o.knobs })
  const r = paintSkeleton(ink, def, size, { ...o, kind })
  const res = ink.toSvg({ w: r.w, h: r.h, pad: o.pad })
  return { ...res, variant: r.variant, kind, nib: r.nib, k: r.k, silhouette: r.silhouette }
}

export interface DieCutOpts extends DrawOpts {
  border?: number
  peel?: boolean | number
  shadow?: boolean
  idPrefix?: string
}

export interface DieCutResult extends SkeletonResult {
  off: number
  border: number
}

export function dieCut(def: ArtDef, size: number, seed: string | number, o: DieCutOpts = {}): DieCutResult {
  const kind = o.kind ?? 'sticker'
  const border = o.border ?? clamp(size * 0.075, 3.5, 8)
  const off = Math.ceil(border + 2)
  const [gw, gh] = def.grid === 24 || def.grid === 64 ? [def.grid, def.grid] : def.grid
  const k = size / Math.max(gw, gh)
  const W = gw * k + 2 * off, H = gh * k + 2 * off
  const tier: Tier = o.tier ?? (size >= 96 ? 'hi' : 'lo')
  const ink = new Ink(`die:${seed}`, { tier, grain: o.grain, calm: o.calm, knobs: o.knobs })
  const id = o.idPrefix ?? `ll-sil-${hashSeed(`${seed}:${size}:${def.parts.length}:${W}`).toString(36)}`
  const art = paintSkeleton(ink, def, size, { silAll: true, ...o, kind, tone: o.tone ?? 'doodle', nib: o.nib ?? clamp(size * (def.nibK ?? 0.055), 1.8, 4.6) }, [off, off])
  const S = art.silhouette
  const bw = 2 * border
  const defs = `<defs><g id="${id}f">${S.fills.map((d) => `<path d="${d}"/>`).join('')}</g><g id="${id}l">${S.lines.map((d) => `<path d="${d}" fill="none"/>`).join('')}</g></defs>`
  const layer = (fill: string, stroke: string, extra: number, op: number, dx = 0, dy = 0): string => {
    const t = dx || dy ? ` transform="translate(${n(dx)} ${n(dy)})"` : ''
    const opa = op < 1 ? ` opacity="${n(op, 100)}"` : ''
    return (
      `<g${t}${opa}><use href="#${id}f" fill="${fill}" stroke="${stroke}" stroke-width="${n(bw + extra)}" stroke-linejoin="round"/>` +
      `<use href="#${id}l" stroke="${stroke}" stroke-width="${n(bw + extra + S.W)}" stroke-linejoin="round" stroke-linecap="round"/></g>`
    )
  }
  let under = defs
  if (o.shadow) under += layer('var(--ll-ink)', 'var(--ll-ink)', 1, 0.1, 0.4, 3.4) + layer('var(--ll-ink)', 'var(--ll-ink)', 0.4, 0.2, 0.2, 1.1)
  under += layer('var(--ll-pencil-mark)', 'var(--ll-pencil-mark)', 1.3, 0.55)
  under += layer('var(--ll-photo)', 'var(--ll-photo)', 0, 1)
  ink.raw(under, 'under')
  ink.grow([0, 0, W, H])
  let res = ink.toSvg({ w: W, h: H, pad: o.pad ?? 2 })
  if (o.peel) res = { ...res, svg: peelCorner(res.svg, S, id, off, border, W, H, o.peel === true ? clamp(size * 0.2, 12, 26) : o.peel, `${seed}`) }
  return { ...res, variant: art.variant, kind, nib: art.nib, k: art.k, silhouette: S, off, border }
}

function peelCorner(svg: string, S: Silhouette, id: string, _off: number, border: number, W: number, H: number, s: number, seed: string): string {
  const R = Math.SQRT1_2
  const d = (p: Pt): number => (p[0] + p[1]) * R
  let dmax = -Infinity
  let tip: Pt = [W, H]
  for (const p of S.pts) {
    if (d(p) > dmax) {
      dmax = d(p)
      tip = p
    }
  }
  dmax += border + 1
  const fold = dmax - s
  const big = 4000
  const at = (dd: number, tt: number): Pt => [(dd + tt) * R, (dd - tt) * R]
  const half = (dd0: number, dd1: number): string => {
    const a = at(dd0, -big), b = at(dd0, big), c = at(dd1, big), e = at(dd1, -big)
    return `M${n(a[0])} ${n(a[1])}L${n(b[0])} ${n(b[1])}L${n(c[0])} ${n(c[1])}L${n(e[0])} ${n(e[1])}Z`
  }
  const tag = hashSeed(`peel:${seed}`).toString(36)
  const keep = `${id}k${tag}`, cut = `${id}r${tag}`, grad = `${id}g${tag}`
  const tt = (tip[0] - tip[1]) * R
  const edge = at(fold, tt)
  const far = at(fold + s * 0.95, tt)
  const m = Math.SQRT2 * fold
  const flap =
    `<g transform="matrix(0 -1 -1 0 ${n(m)} ${n(m)})"><g clip-path="url(#${cut})">` +
    `<use href="#${id}f" fill="url(#${grad})" stroke="url(#${grad})" stroke-width="${n(2 * border)}" stroke-linejoin="round"/>` +
    `<use href="#${id}l" stroke="url(#${grad})" stroke-width="${n(2 * border + S.W)}" stroke-linejoin="round" stroke-linecap="round"/></g></g>`
  const crease = `<path d="M${n(at(fold, tt - s * 1.6)[0])} ${n(at(fold, tt - s * 1.6)[1])}L${n(at(fold, tt + s * 1.6)[0])} ${n(at(fold, tt + s * 1.6)[1])}" stroke="var(--ll-pencil-mark)" stroke-opacity=".35" stroke-width=".8" stroke-linecap="round"/>`
  const defs =
    `<defs><clipPath id="${keep}"><path d="${half(-big, fold)}"/></clipPath><clipPath id="${cut}"><path d="${half(fold, big)}"/></clipPath>` +
    `<linearGradient id="${grad}" gradientUnits="userSpaceOnUse" x1="${n(edge[0])}" y1="${n(edge[1])}" x2="${n(far[0])}" y2="${n(far[1])}">` +
    `<stop offset="0" stop-color="var(--ll-pencil-mark)" stop-opacity=".55"/><stop offset=".3" stop-color="var(--ll-paper)"/><stop offset="1" stop-color="var(--ll-photo)"/></linearGradient></defs>`
  return `${defs}<g clip-path="url(#${keep})">${svg}</g>${flap}${crease}`
}

export function renderSticker(def: StickerDef, size: number, seed: string | number, o: DieCutOpts = {}): DieCutResult | InkResult {
  if (isGen(def)) {
    if (def.gen === 'badge') return dieCut(badgeSkeleton(def.text, def), size, seed, o)
    return stamp(def.text, def.shape, { ...def, seed })
  }
  return dieCut(def, size, seed, o)
}

const CACHE = new Map<string, unknown>()

export function memo<T>(key: string, make: () => T, max = 400): T {
  const hit = CACHE.get(key)
  if (hit !== undefined) {
    CACHE.delete(key)
    CACHE.set(key, hit)
    return hit as T
  }
  const v = make()
  CACHE.set(key, v)
  if (CACHE.size > max) CACHE.delete(CACHE.keys().next().value as string)
  return v
}

export type { BBox }
